            "<참새정>이 모종의 이유로 곧 문을 닫을 것이라는 사실을 알게 된 미식연구회는, 급양부까지 회유하여 <참새정>을 되살리려 한다. 그러나 그렇게 하기 위해서는 거대 유통 기업 <냐오푸드>와의 문제를 먼저 해결해야 하는데……"
