                "en": "At the traditional teahouse Momoyodou in the Hyakkiyako shopping district, Sensei is warmly welcomed by Shizuko and Pina of the Festival Operations Department. Just then, a commotion breaks out and attackers suddenly appear.",
                "kr": "상점가에서 난리를 피우는 길거리 망량즈 속에는 어째선지 이즈나도 함께였다. 선생님을 보고 당황하여 달아난 이즈나. 시즈코는 골칫거리 망량즈를 해결하기 위해 선생님에게 도움을 요청한다.",
                "jp": "百鬼夜行商店街の伝統茶屋「百夜堂」に到着した先生は、祭り運営管理部のシズコとフィーナから熱烈な歓迎を受ける。ところがその時、騒ぎとともに襲撃者たちが現れる。",
                "tw": "老師來到百鬼夜行商業街的傳統茶館百夜堂，受到慶典運營管理部靜子與菲娜的熱烈歡迎。就在這時，伴隨著一陣騷亂，襲擊者突然出現。",
                "th": "Sensei มาถึงร้านน้ำชาโมโมโยโดในย่านการค้าเฮียคคิยาโคะ และได้รับการต้อนรับอย่างอบอุ่นจากชิซึโกะกับพินะแห่งฝ่ายจัดการเทศกาล ทันใดนั้นกลุ่มผู้บุกรุกก็ปรากฏตัวขึ้นท่ามกลางความวุ่นวาย"
