                "th": "ขณะเดินตรวจถนนเรดวินเทอร์ที่อบอวลด้วยบรรยากาศเทศกาล เชริโนถูกฝ่ายแรงงานที่กำลังประท้วงจับตัวและมัดไว้กับกองฟืน"
