                "tw": "成功發動政變後正悠閒享受勝利的真里奈，從親衛隊員口中得知切里諾正率領眾多學生進軍而來，頓時大驚失色。",
                "th": "มารินะกำลังเพลิดเพลินกับชัยชนะหลังรัฐประหารสำเร็จ แต่ต้องตกตะลึงเมื่อองครักษ์รายงานว่าเชริโนนำเหล่านักเรียนจำนวนมากบุกเข้ามา"
