                "cn": "击败政变势力并夺回会长职位的切里诺，果断肃清了真里奈。然而伊万库帕拉节当天，曾参与革命的学生们因切里诺没有履行承诺而再次发动政变，切里诺又一次下台。",
                "kr": "쿠데타 세력을 물리치고 회장 자리를 되찾은 체리노는 마리나를 단호히 숙청한다. 하지만 이반 쿠팔라 축제 당일, 혁명에 동참했던 학생들이 공약을 지키라며 다시 쿠데타를 일으키고 체리노는 또다시 실각한다.",
                "en": "After defeating the coup forces and reclaiming the presidency, Cherino decisively purges Marina. But on Ivan Kupala day, the students who joined the revolution stage another coup over Cherino’s broken promises—and Cherino is ousted once again.",
