                "tw": "擊敗政變勢力並奪回會長職位的切里諾，果斷肅清了真里奈。然而伊萬庫帕拉節當天，曾參與革命的學生們因切里諾沒有履行承諾而再次發動政變，切里諾又一次下台。",
